static int hex_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

int parse_hex_string(const char *hex, size_t hex_len, unsigned char *out, size_t out_cap) {
    if (hex == NULL || out == NULL || hex_len % 2 != 0) return -1;
    size_t bytes_needed = hex_len / 2;
